source.exploreUrl:
@js:
var url=source.key,
html=java.ajax(url);
a=org.jsoup.Jsoup.parse(html)
.select("nav.nav li:lt(10) a");
var arr=[],sort=[];
if(html&&a){
	arr=Array.from(a, x=>[
		x.text(),String(x.attr("href"))
		.replace(/_1/,"_{{page}}")
		.replace(/quanben.+(?!1).?$/,
			"$&<,{{page}}/>")] );
		sort=arr.map(([title,link])=>({
    "title": title,
    "url": link,
    "style": {
      "layout_flexGrow": 1,
       "layout_flexBasisPercent": 0.2
    }
  }));

  JSON.stringify(sort)

	}else java.toast("发现列表获取失败！")

